/* ======================= EJERCICIOS DE FUNCIONES ======================= */
EX.push(
{ id:'F1', src:'extra', t:'¿Es función?',
  q:`<p>Sean A = {1, 2, 3} y B = {x, y}. Para cada relación de A en B decide si es función y, si no, por qué.</p>`,
  parts:[
    { l:'a) <code>{(1,x), (2,x), (3,y)}</code>', o:OPT_REL, a:0, w:'Cada elemento de A aparece una sola vez. Que 1 y 2 vayan a x está permitido.' },
    { l:'b) <code>{(1,x), (2,y)}</code>', o:OPT_REL, a:1, w:'Al 3 no le toca nada.' },
    { l:'c) <code>{(1,x), (1,y), (2,x), (3,y)}</code>', o:OPT_REL, a:2, w:'El 1 tiene dos imágenes, x y y.' },
    { l:'d) <code>{(1,y), (2,y), (3,y)}</code>', o:OPT_REL, a:0, w:'Una función constante: todos a y. Es válida.' },
    { l:'e) <code>{(1,x), (2,z), (3,y)}</code>', o:OPT_REL, a:3, w:'z no está en B, así que (2, z) no es pareja de A × B.' } ],
  sol:`<p>La prueba: cada elemento de A debe aparecer <b>exactamente una vez</b> como primer elemento, y cada pareja debe estar en A × B. a) y d) cumplen; b) deja fuera al 3; c) repite al 1; e) usa z, que no está en B.</p>` },
{ id:'F2', src:'extra', t:'Producto cartesiano',
  q:`<p>Sean A = {1, 2} y B = {a, b, c}.</p>`,
  parts:[
    { l:'a) Escribe A × B como conjunto de parejas ordenadas', k:'set', a:'{(1,a),(1,b),(1,c),(2,a),(2,b),(2,c)}', traps:[['{(a,1),(b,1),(c,1),(a,2),(b,2),(c,2)}','Esas parejas son de B × A: en A × B el primer elemento sale de A.']] },
    { l:'b) ¿Cuántas parejas tiene B × A?', a:'3*2', v:'6' } ],
  sol:`<p>A × B junta cada elemento de A con cada uno de B: 2 · 3 = 6 parejas (regla del producto). B × A también tiene 6, pero con las parejas al revés: (a, 1), (a, 2), …</p>` },
{ id:'F3', src:'diap', t:'Diagramas: ¿cuáles son funciones?',
  q:`<p>X = {a, b, c} e Y = {1, 2, 3, 4}. ¿Cuáles de estos diagramas definen una función de X en Y?</p><div data-arrows="fa fb fc"></div>`,
  parts:[
    { l:'a) Diagrama (a)', o:OPT_DIAG, a:1, w:'De b no sale ninguna flecha.' },
    { l:'b) Diagrama (b)', o:OPT_DIAG, a:2, w:'De b salen dos flechas, a 2 y a 3.' },
    { l:'c) Diagrama (c)', o:OPT_DIAG, a:0, w:'De cada elemento de X sale una sola flecha; que b y c lleguen al 3 está permitido.' } ],
  sol:`<p>Revisa la columna de la izquierda: de cada punto debe salir exactamente una flecha. Solo (c) cumple.</p>` },
{ id:'F4', src:'extra', t:'Cuántas relaciones y cuántas funciones',
  q:`<p>Sea A un conjunto con 2 elementos y B uno con 3.</p>`,
  parts:[
    { l:'a) ¿Cuántas relaciones hay de A en B? (Una relación es cualquier subconjunto de A × B.)', a:'2^6', v:'64', traps:[['6','Eso es el número de parejas de A × B; las relaciones son subconjuntos de esas parejas.']] },
    { l:'b) ¿Cuántas de ellas son funciones?', a:'3^2', v:'9', traps:[['2^3','Cada elemento de A (son 2) escoge su imagen entre 3: es 3·3, no 2·2·2.'],['P(3,2)','Eso cuenta solo las inyectivas; dos elementos de A sí pueden ir al mismo de B.']] } ],
  pista:'a) A × B tiene 6 parejas y cada una puede estar o no estar. b) Cada elemento de A elige una imagen.',
  sol:`<p>a) A × B tiene 2·3 = 6 parejas y cada una puede estar o no en la relación: 2⁶ = 64.</p><p>b) Para ser función, cada uno de los 2 elementos de A escoge exactamente una imagen entre 3: 3·3 = 9. Así se ve el puente con el conteo.</p>`,
  bf:() => { const pairs = []; ['1','2'].forEach(a => ['x','y','z'].forEach(b => pairs.push([a, b]))); const subs = powA([0,1],6); return [subs.length, countIf(subs, s => { const R = pairs.filter((_, i) => s[i]); return ['1','2'].every(a => countIf(R, p => p[0] === a) === 1); })]; } },
{ id:'F5', src:'diap', t:'El ejercicio de la clase (I)',
  q:`<p>Sea X = {a, b, c} e Y = {1, 2, 3, 4}, y f la función del diagrama.</p><div data-arrows="fej"></div>`,
  parts:[
    { l:'A) Dominio de f', k:'set', a:'{a,b,c}' },
    { l:'A) Codominio de f', k:'set', a:'{1,2,3,4}', traps:[['{2,4}','Ese es el rango. El codominio es todo Y, aunque no todos reciban flecha.']] },
    { l:'B) f(a) =', k:'val', a:'2' },
    { l:'B) f(b) =', k:'val', a:'4' },
    { l:'B) f(c) =', k:'val', a:'2' },
    { l:'C) Rango de f', k:'set', a:'{2,4}', traps:[['{1,2,3,4}','Ese es el codominio. El rango son solo los que reciben flecha.']] } ],
  sol:`<p>Dominio X = {a, b, c}; codominio Y = {1, 2, 3, 4}. Siguiendo las flechas: f(a) = 2, f(b) = 4, f(c) = 2. El rango son los valores que sí se alcanzan: {2, 4}.</p>` },
{ id:'F6', src:'diap', t:'El ejercicio de la clase (II)',
  q:`<p>Misma función: f(a) = 2, f(b) = 4, f(c) = 2, con Y = {1, 2, 3, 4}.</p><div data-arrows="fej"></div>`,
  parts:[
    { l:'D) ¿Es c una imagen inversa de 2?', o:SINO, a:0, w:'f(c) = 2.' },
    { l:'D) ¿Es b una imagen inversa de 3?', o:SINO, a:1, w:'f(b) = 4, no 3.' },
    { l:'E) Imagen inversa de 2', k:'set', a:'{a,c}' },
    { l:'E) Imagen inversa de 4', k:'set', a:'{b}' },
    { l:'E) Imagen inversa de 1', k:'set', a:'∅', traps:[['{1}','Se piden los elementos de X que llegan al 1. Ninguno llega.']] },
    { l:'F) f como conjunto de parejas ordenadas', k:'set', a:'{(a,2),(b,4),(c,2)}', traps:[['{(2,a),(4,b),(2,c)}','El primer elemento de cada pareja es el del dominio: (a, 2), no (2, a).']] } ],
  sol:`<p>La imagen inversa de y son los x con f(x) = y: de 2 son {a, c}, de 4 es {b} y de 1 es ∅ (nadie llega). Como parejas: f = {(a, 2), (b, 4), (c, 2)}.</p>` },
{ id:'F7', src:'extra', t:'Cuadrados en un dominio chico',
  q:`<p>Sea A = {−2, −1, 0, 1, 2} y f : A → ℤ con f(x) = x².</p>`,
  parts:[
    { l:'a) Rango de f', k:'set', a:'{0,1,4}' },
    { l:'b) Imagen inversa de 4', k:'set', a:'{-2,2}' },
    { l:'c) Imagen inversa de 3', k:'set', a:'∅' },
    { l:'d) ¿Cuántos elementos tiene la imagen inversa de 1?', a:'2', v:'2' } ],
  sol:`<p>f(−2) = f(2) = 4, f(−1) = f(1) = 1 y f(0) = 0. Rango {0, 1, 4}. La imagen inversa de 4 es {−2, 2}, la de 1 es {−1, 1} (2 elementos) y la de 3 es vacía: 3 no es el cuadrado de ningún elemento de A.</p>` },
{ id:'F8', src:'diap', t:'Subconjuntos y tamaños',
  q:`<p>La función de la clase: f : 𝒫({a, b, c}) → ℤ, f(x) = número de elementos de x.</p>`,
  parts:[
    { l:'a) ¿Cuántos elementos tiene el dominio?', a:'2^3', v:'8', traps:[['3','El dominio es el conjunto potencia: todos los subconjuntos de {a, b, c}, incluyendo ∅ y el completo.']] },
    { l:'b) Rango de f', k:'set', a:'{0,1,2,3}' },
    { l:'c) Imagen inversa de 2', k:'set', a:'{{a,b},{a,c},{b,c}}', ph:'Conjunto de conjuntos, p. ej. {{a,b}, …}' },
    { l:'d) Imagen inversa de 5', k:'set', a:'∅' } ],
  sol:`<p>𝒫({a, b, c}) tiene 2³ = 8 subconjuntos. Sus tamaños van de 0 a 3, así que el rango es {0, 1, 2, 3} aunque el codominio sea todo ℤ. Los de tamaño 2 son {a, b}, {a, c} y {b, c}. Ningún subconjunto tiene 5 elementos.</p>` },
{ id:'F9', src:'diap', t:'Operación módulo',
  q:`<p>Calcula. Puedes escribir el número o la expresión, por ejemplo <code>100 mod 7</code>.</p>`,
  parts:[
    { l:'a) 7 mod 2', a:'7 mod 2', v:'1' },
    { l:'b) 100 mod 7', a:'100 mod 7', v:'2' },
    { l:'c) 88 minutos son 1 hora y ¿cuántos minutos?', a:'88 mod 60', v:'28' },
    { l:'d) 14 meses son 1 año y ¿cuántos meses?', a:'14 mod 12', v:'2' } ],
  sol:`<p>a mod n es el residuo: 7 = 3·2 + 1; 100 = 14·7 + 2; 88 = 1·60 + 28; 14 = 1·12 + 2.</p>` },
{ id:'F10', src:'diap', t:'¿f = g?',
  q:`<p>Sea A₃ = {0, 1, 2} y f, g : A₃ → A₃ con f(x) = (x² + x + 1) mod 3 y g(x) = (x + 2)² mod 3. Llena la tabla.</p>`,
  parts:[
    { l:'f(0) =', a:'1', v:'1' }, { l:'f(1) =', a:'0', v:'0' }, { l:'f(2) =', a:'1', v:'1' },
    { l:'g(0) =', a:'1', v:'1' }, { l:'g(1) =', a:'0', v:'0' }, { l:'g(2) =', a:'1', v:'1' },
    { l:'¿f = g?', o:SINO, a:0, w:'Coinciden en los tres elementos del dominio.' } ],
  sol:`<div class="tw"><table class="t"><tr><th>x</th><th>x² + x + 1</th><th>f(x)</th><th>(x + 2)²</th><th>g(x)</th></tr><tr><td>0</td><td>1</td><td>1</td><td>4</td><td>1</td></tr><tr><td>1</td><td>3</td><td>0</td><td>9</td><td>0</td></tr><tr><td>2</td><td>7</td><td>1</td><td>16</td><td>1</td></tr></table></div><p>Dan lo mismo en cada x de A₃, así que f = g aunque las fórmulas sean distintas.</p>` },
{ id:'F11', src:'diap', t:'Funciones del producto cartesiano',
  q:`<p>m : ℝ × ℝ → ℝ con m(a, b) = ab, y r : ℝ × ℝ → ℝ × ℝ con r(a, b) = (−a, b). Las parejas escríbelas como <code>(-2, 1)</code>; puedes usar fracciones como <code>-1/2</code>.</p>`,
  parts:[
    { l:'m(2, 1) =', a:'2', v:'2' }, { l:'m(−1, −1) =', a:'1', v:'1' }, { l:'m(½, −3) =', a:'-3/2', v:'-3/2' },
    { l:'r(2, 1) =', k:'val', a:'(-2,1)', ph:'Una pareja, p. ej. (3, 4)' }, { l:'r(−1, −1) =', k:'val', a:'(1,-1)', ph:'Una pareja, p. ej. (3, 4)' }, { l:'r(½, −3) =', k:'val', a:'(-1/2,-3)', ph:'Una pareja, p. ej. (3, 4)' } ],
  sol:`<p>m multiplica: 2·1 = 2, (−1)(−1) = 1, ½·(−3) = −3/2. r le cambia el signo solo a la primera coordenada: (−2, 1), (1, −1), (−½, −3).</p>` },
{ id:'F12', src:'diap', t:'Función booleana de paridad',
  q:`<p>f : {0,1}³ → {0,1} con f(x₁, x₂, x₃) = (x₁ + x₂ + x₃) mod 2.</p>`,
  parts:[
    { l:'f(1, 0, 1) =', a:'0', v:'0' }, { l:'f(1, 1, 1) =', a:'1', v:'1' }, { l:'f(0, 1, 0) =', a:'1', v:'1' },
    { l:'¿En cuántas de las 8 entradas vale 1?', a:'4', v:'4' },
    { l:'¿Cuántas funciones booleanas distintas de 3 variables existen?', a:'2^8', v:'256', traps:[['2^3','Eso es el número de entradas (renglones de la tabla). Cada renglón puede dar 0 o 1: 2 elevado a 8.'],['16','Esas son las de 2 variables (2⁴). Con 3 variables hay 8 renglones.']] } ],
  sol:`<p>f vale 1 cuando hay una cantidad impar de unos: (0,0,1), (0,1,0), (1,0,0) y (1,1,1). Son 4 de 8. Como cada uno de los 2³ = 8 renglones puede dar 0 o 1, hay 2⁸ = 256 funciones booleanas de 3 variables.</p>`,
  bf:() => [null, null, null, countIf(powA([0,1],3), p => (p[0] + p[1] + p[2]) % 2 === 1), null] },
{ id:'F13', src:'diap', t:'¿Son sobreyectivas? (de la clase)',
  q:`<p>Decide si cada función es sobreyectiva.</p>`,
  parts:[
    { l:'1. f : ℝ → ℝ, f(x) = x', o:SINO, a:0, w:'Cada y es imagen de x = y.' },
    { l:'2. h : ℤ → ℤ, h(x) = 2x', o:SINO, a:1, w:'Los impares no son 2x para ningún entero.' },
    { l:'3. g : ℝ → ℝ, g(x) = sen x', o:SINO, a:1, w:'El seno nunca pasa de 1: el 2 no tiene preimagen.' },
    { l:'4. k : {a,b,c} → {1,2,3}, k(a) = 1, k(b) = 2, k(c) = 3', o:SINO, a:0, w:'Los tres números reciben una letra.' },
    { l:'5. m : ℕ → ℕ, m(n) = n + 1 (con ℕ = {1, 2, 3, …})', o:SINO, a:1, w:'El 1 no es n + 1 para ningún natural.' } ],
  sol:`<p>Para cada una, toma un y del codominio y busca su x. Fallan h (el 1 no tiene preimagen entera), g (el 2 no tiene preimagen) y m (el 1 no tiene preimagen). Se arreglan achicando el codominio: h : ℤ → 2ℤ, g : ℝ → [−1, 1], m : ℕ → {2, 3, 4, …}.</p>` },
{ id:'F14', src:'extra', t:'Clasifica cada función',
  q:`<p>Para cada función elige su clasificación.</p>`,
  parts:[
    { l:'a) f : ℝ → ℝ, f(x) = x³', o:OPT_CLAS, a:2, w:'Cada real tiene una única raíz cúbica real.' },
    { l:'b) f : ℝ → ℝ, f(x) = x²', o:OPT_CLAS, a:3, w:'f(−1) = f(1) y los negativos no tienen preimagen.' },
    { l:'c) f : ℕ → ℕ, f(n) = 2n', o:OPT_CLAS, a:0, w:'Distintos n dan distintos 2n, pero los impares no se alcanzan.' },
    { l:'d) f : ℤ → ℤ, f(n) = ⌊n/2⌋ (la mitad redondeada hacia abajo)', o:OPT_CLAS, a:1, w:'f(0) = f(1) = 0, y cualquier m se alcanza con n = 2m.' },
    { l:'e) f : ℝ → ℝ, f(x) = 4x − 1', o:OPT_CLAS, a:2, w:'Es el ejemplo de la clase: inyectiva y, con x = (y + 1)/4, sobreyectiva.' } ],
  sol:`<p>Para inyectividad busca dos x distintas con la misma imagen (contraejemplo) o demuestra que no existen. Para sobreyectividad despeja x y revisa que esté en el dominio.</p>` },
{ id:'F15', src:'extra', t:'Clasifica los diagramas',
  q:`<p>Clasifica cada función dada por su diagrama.</p><div data-arrows="ia ib ic"></div>`,
  parts:[
    { l:'a) Diagrama (a)', o:OPT_CLAS, a:0, w:'Nadie recibe dos flechas, pero el 2 no recibe ninguna.' },
    { l:'b) Diagrama (b)', o:OPT_CLAS, a:1, w:'Todos reciben flecha, pero el 3 recibe dos.' },
    { l:'c) Diagrama (c)', o:OPT_CLAS, a:2, w:'Cada uno de Y recibe exactamente una flecha.' } ],
  sol:`<p>Mira la columna de la derecha: si alguien recibe dos flechas, no es inyectiva; si alguien no recibe ninguna, no es sobreyectiva.</p>` },
{ id:'F16', src:'diap', t:'Contraejemplos y preimágenes',
  q:`<p>Usa las definiciones para responder.</p>`,
  parts:[
    { l:'a) g : ℤ → ℤ, g(n) = n² no es inyectiva. Da un entero distinto de 3 con g(n) = g(3).', a:'-3', v:'-3' },
    { l:'b) h : ℤ → ℤ, h(x) = 2x no es sobreyectiva. Da un entero del codominio que no tenga preimagen.', a:'1', test:odd, testMsg:'Ese sí tiene preimagen: es par, así que es 2 por algún entero.', show:'Cualquier impar, por ejemplo 1' },
    { l:'c) f : ℝ → ℝ, f(x) = 4x − 1. ¿Qué x cumple f(x) = 11?', a:'3', v:'3' },
    { l:'d) Para un y cualquiera, ¿qué x cumple f(x) = y? Escríbelo en términos de y.', k:'expr', vars:['y'], a:'(y+1)/4', ph:'Expresión en y, p. ej. (y-3)/2', traps:[['(y-1)/4','Despeja con cuidado: 4x − 1 = y → 4x = y + 1.'],['4y-1','Esa es f(y); se pide despejar x.']] } ],
  sol:`<p>a) g(−3) = 9 = g(3). b) Cualquier impar: 2x siempre es par. c) 4x − 1 = 11 → x = 3. d) 4x − 1 = y → x = (y + 1)/4. Como esa x siempre es real, f es sobreyectiva.</p>` },
{ id:'F17', src:'diap', t:'Sucesión y cúbica (de la clase)',
  q:`<p>Sea f : ℤ → ℤ la función sucesión, f(n) = n + 1, y g : ℤ → ℤ la función cúbica, g(n) = n³. Escribe las expresiones en términos de n, por ejemplo <code>(n+1)^3</code>.</p>`,
  parts:[
    { l:'a) (g ∘ f)(n) =', k:'expr', a:'(n+1)^3', traps:[['n^3+1','Esa es f ∘ g: primero el cubo y luego +1. En g ∘ f primero va f.']] },
    { l:'b) (f ∘ g)(n) =', k:'expr', a:'n^3+1', traps:[['(n+1)^3','Esa es g ∘ f.']] },
    { l:'c) (g ∘ f)(2) =', a:'27', v:'27' },
    { l:'d) (f ∘ g)(2) =', a:'9', v:'9' } ],
  sol:`<p>(g ∘ f)(n) = g(f(n)) = g(n + 1) = (n + 1)³. (f ∘ g)(n) = f(g(n)) = f(n³) = n³ + 1. En n = 2: 3³ = 27 y 2³ + 1 = 9. No son iguales: la composición no conmuta.</p>` },
{ id:'F18', src:'diap', t:'Composición con diagrama (de la clase)',
  q:`<p>Con las funciones f : X → Y y g : Y → Z del diagrama:</p><div data-arrows="comp"></div>`,
  parts:[
    { l:'(g ∘ f)(1) =', k:'val', a:'z' }, { l:'(g ∘ f)(2) =', k:'val', a:'y' }, { l:'(g ∘ f)(3) =', k:'val', a:'y' },
    { l:'Dominio de g ∘ f', k:'set', a:'{1,2,3}', traps:[['{a,b,c,d,e}','Ese es el dominio de g. La composición sale de X.']] },
    { l:'Rango de g ∘ f', k:'set', a:'{y,z}', traps:[['{x,y,z}','La x no se alcanza partiendo de X.']] } ],
  sol:`<p>(g ∘ f)(1) = g(f(1)) = g(c) = z; (g ∘ f)(2) = g(b) = y; (g ∘ f)(3) = g(a) = y. El dominio es {1, 2, 3} y el rango {y, z}.</p>` },
{ id:'F19', src:'extra', t:'Composición con fórmulas',
  q:`<p>Sean f(x) = x − 4 y g(x) = 2x, de ℝ en ℝ. Escribe en términos de x.</p>`,
  parts:[
    { l:'a) (g ∘ f)(x) =', k:'expr', vars:['x'], a:'2*(x-4)', ph:'Expresión en x', traps:[['2x-4','Esa es f ∘ g: primero duplicas y luego restas 4.']] },
    { l:'b) (f ∘ g)(x) =', k:'expr', vars:['x'], a:'2x-4', ph:'Expresión en x', traps:[['2*(x-4)','Esa es g ∘ f.']] },
    { l:'c) (f ∘ f)(x) =', k:'expr', vars:['x'], a:'x-8', ph:'Expresión en x' } ],
  sol:`<p>(g ∘ f)(x) = g(x − 4) = 2(x − 4) = 2x − 8. (f ∘ g)(x) = f(2x) = 2x − 4. (f ∘ f)(x) = (x − 4) − 4 = x − 8.</p>` },
{ id:'F20', src:'extra', t:'Inversas',
  q:`<p>Encuentra las inversas cuando existan.</p>`,
  parts:[
    { l:'a) f(x) = 4x − 1. f⁻¹(y) =', k:'expr', vars:['y'], a:'(y+1)/4', ph:'Expresión en y', traps:[['(y-1)/4','Si y = 4x − 1, entonces y + 1 = 4x.']] },
    { l:'b) f⁻¹(11) =', a:'3', v:'3' },
    { l:'c) h : ℤ → 2ℤ, h(n) = 2n. h⁻¹(10) =', a:'5', v:'5' },
    { l:'d) ¿g : ℤ → ℤ, g(n) = n² tiene inversa?', o:['Sí', 'No, porque no es biyectiva'], a:1, w:'No es inyectiva (g(−2) = g(2)) ni sobreyectiva.' } ],
  sol:`<p>Para invertir, despeja x de y = f(x): y = 4x − 1 → x = (y + 1)/4, y f⁻¹(11) = 3. h⁻¹(y) = y/2, así que h⁻¹(10) = 5. g no es biyectiva, así que no tiene inversa.</p>` },
{ id:'F21', src:'extra', t:'Tabla hash',
  q:`<p>Una tabla hash tiene 7 casillas (0 a 6) y usa h(k) = k mod 7.</p>`,
  parts:[
    { l:'h(15) =', a:'1', v:'1' }, { l:'h(22) =', a:'1', v:'1' }, { l:'h(40) =', a:'5', v:'5' },
    { l:'¿Qué pareja de claves choca?', o:['15 y 22', '22 y 40', '15 y 40', 'Ninguna'], a:0, w:'Las dos caen en la casilla 1.' },
    { l:'¿Cuál es el mínimo de claves que garantiza al menos una colisión?', a:'8', v:'8', traps:[['7','Con 7 claves todavía pueden caer cada una en su casilla. La octava ya no tiene lugar libre.']] } ],
  sol:`<p>15 = 2·7 + 1, 22 = 3·7 + 1 y 40 = 5·7 + 5. 15 y 22 chocan: h no es inyectiva. Con 8 claves y 7 casillas alguna casilla recibe dos (principio del palomar).</p>` },
{ id:'F22', src:'extra', t:'Zigzag de ℕ a ℤ',
  q:`<p>La biyección f : ℕ → ℤ empareja 1 → 0, 2 → 1, 3 → −1, 4 → 2, 5 → −2, 6 → 3, … En fórmula: f(n) = n/2 si n es par y f(n) = −(n − 1)/2 si n es impar.</p>`,
  parts:[
    { l:'f(6) =', a:'3', v:'3' }, { l:'f(7) =', a:'-3', v:'-3' }, { l:'f(10) =', a:'5', v:'5' },
    { l:'¿Qué natural va al −4?', a:'9', v:'9' }, { l:'¿Qué natural va al 100?', a:'200', v:'200' } ],
  sol:`<p>Los pares van a los positivos (n/2) y los impares a los negativos y al 0. −4 viene de un impar: −(n − 1)/2 = −4 → n = 9. 100 viene de n = 200.</p>`,
  bf:() => { const f = n => n % 2 === 0 ? n / 2 : -(n - 1) / 2; return [f(6), f(7), f(10), range(1,100).find(n => f(n) === -4), range(1,400).find(n => f(n) === 100)]; } },
{ id:'F23', src:'extra', t:'Biyecciones con los naturales',
  q:`<p>ℕ = {1, 2, 3, …}.</p>`,
  parts:[
    { l:'a) f(n) = 2n − 1 empareja ℕ con los impares. f(5) =', a:'9', v:'9' },
    { l:'b) ¿Qué n cumple 2n − 1 = 31?', a:'16', v:'16' },
    { l:'c) f(n) = 3n empareja ℕ con los múltiplos de 3. ¿Qué n va al 51?', a:'17', v:'17' },
    { l:'d) Escribe una biyección de ℕ a los pares positivos', k:'expr', a:'2n', ph:'Expresión en n' } ],
  sol:`<p>Cada una se invierte despejando: n = (y + 1)/2 para los impares y n = y/3 para los múltiplos de 3. Para los pares positivos, f(n) = 2n.</p>` },
{ id:'F24', src:'extra', t:'Contar es emparejar',
  q:`<p>Cuenta emparejando con {1, 2, …, n}.</p>`,
  parts:[
    { l:'a) ¿Cuántos enteros hay del 15 al 87, incluyendo ambos?', a:'73', v:'73', traps:[['72','87 − 15 olvida contar uno de los extremos. Empareja 15 → 1, 16 → 2, …, 87 → 73.']] },
    { l:'b) ¿Cuántos múltiplos de 4 hay entre 1 y 100?', a:'25', v:'25' },
    { l:'c) ¿Cuántos números de 3 cifras (del 100 al 999) hay?', a:'900', v:'900', traps:[['899','999 − 100 = 899 se salta uno: hay que sumar 1.']] } ],
  sol:`<p>a) n ↦ n − 14 empareja {15, …, 87} con {1, …, 73}. b) 4k ↦ k empareja los múltiplos de 4 con {1, …, 25}. c) n ↦ n − 99 da {1, …, 900}.</p>`,
  bf:() => [range(15,87).length, countIf(range(1,100), n => n % 4 === 0), range(100,999).length] }
);

/* ======================= EJERCICIOS DE CONTEO ======================= */
const finTorneo = t => { const a = countIf(t.split(''), x => x === 'A'), b = t.length - a, l2 = t.slice(-2); return l2 === 'AA' || l2 === 'BB' || a === 3 || b === 3; };
const finSerie = t => { const a = countIf(t.split(''), x => x === 'A'); return a === 2 || t.length - a === 2; };
const contarSeries = (fin, max) => { let n = 0; for (let L = 1; L <= max; L++) powA(['A','B'], L).forEach(p => { const s = p.join(''); if (fin(s) && !range(1, L - 1).some(k => fin(s.slice(0, k)))) n++; }); return n; };
EX.push(
{ id:'D1', src:'diap', t:'Torneo A contra B',
  q:`<p>Los equipos A y B juegan entre sí hasta que uno gane dos juegos seguidos o gane un total de tres juegos. ¿De cuántas formas se puede ganar el torneo?</p>`,
  a:'10', v:'10', traps:[['2^5','No siempre se juegan 5 juegos: el torneo se acaba en cuanto alguien gana dos seguidos.']],
  pista:'Dibuja el árbol: cada nivel es un juego y una rama se corta en cuanto alguien gana.',
  sol:`<p>Las hojas del árbol son AA, ABB, ABAA, ABABA, ABABB, BB, BAA, BABB, BABAB y BABAA: 10 formas.</p><div data-tree="torneo"></div>`,
  bf:() => contarSeries(finTorneo, 5) },
{ id:'D2', src:'diap', t:'Las monedas de Tony',
  q:`<p>Tony lanza una moneda 5 veces. Cada lanzamiento es cara o cruz. ¿De cuántas maneras puede lanzarla sin tener 2 caras seguidas?</p>`,
  a:'13', v:'13', traps:[['2^5','Ese es el total sin restricción. Quita las secuencias con dos caras seguidas.']],
  pista:'En el árbol, después de una cara solo puede venir cruz.',
  sol:`<div data-tree="monedas"></div>`,
  bf:() => countIf(powA(['C','X'],5), p => !p.join('').includes('CC')) },
{ id:'D3', src:'diap', t:'Oficiales con restricciones',
  q:`<p>Presidente, tesorero y secretario se eligen entre Ann, Bob, Cyd y Dan. Ann no puede ser presidente y el secretario debe ser Cyd o Dan. ¿De cuántas formas se pueden elegir los oficiales?</p>`,
  a:'8', v:'8', traps:[['P(4,3)','Esas son todas las directivas sin restricciones. Quita las que tienen a Ann de presidente o a un secretario que no sea Cyd ni Dan.']],
  sol:`<div data-tree="oficiales"></div><p>Otra forma: elige primero al secretario (Cyd o Dan, 2 formas), luego al presidente (no Ann ni el secretario: 2 formas) y al tesorero (los 2 que quedan): 2·2·2 = 8.</p>`,
  bf:() => countIf(permsA(['Ann','Bob','Cyd','Dan'],3), p => p[0] !== 'Ann' && (p[2] === 'Cyd' || p[2] === 'Dan')) },
{ id:'D4', src:'diap', t:'Unidades de E/S y CPU',
  q:`<p>Una instalación tiene cuatro unidades de entrada/salida (A, B, C, D) y tres unidades centrales de procesamiento (X, Y, Z). Cualquier unidad de E/S se puede emparejar con cualquier CPU. ¿De cuántas formas se puede emparejar una unidad de E/S con una CPU?</p>`,
  a:'4*3', v:'12', traps:[['4+3','Se elige una unidad de E/S y una CPU: se multiplica.']],
  sol:`<div data-tree="es"></div>` },
{ id:'D5', src:'extra', t:'Serie al mejor de tres',
  q:`<p>A y B juegan una serie al mejor de tres: gana quien gane 2 juegos. ¿De cuántas formas puede desarrollarse la serie?</p>`,
  a:'6', v:'6', traps:[['2^3','No siempre se juega el tercer juego.'],['4','Cuenta también las series que llegan al tercer juego: ABA, ABB, BAB, BAA.']],
  sol:`<div data-tree="serie"></div>`,
  bf:() => contarSeries(finSerie, 3) },
{ id:'D6', src:'extra', t:'Cuatro volados sin dos caras seguidas',
  q:`<p>Lanzas una moneda 4 veces. ¿Cuántas secuencias no tienen dos caras seguidas?</p>`,
  a:'8', v:'8', sol:`<p>Con el mismo árbol de Tony pero de 4 niveles: CXCX, CXXC, CXXX, XCXC, XCXX, XXCX, XXXC, XXXX = 8. (Curiosidad: 2, 3, 5, 8, 13… es la sucesión de Fibonacci.)</p>`,
  bf:() => countIf(powA(['C','X'],4), p => !p.join('').includes('CC')) },
{ id:'D7', src:'diap', t:'Yogurt helado',
  q:`<p>Una tienda de yogurt helado te deja elegir un sabor (vainilla, fresa, limón, cereza o melocotón), un topping (chocolate rallado, caramelo triturado o cacahuate triturado) y un extra (crema batida o coco rallado).</p>`,
  parts:[
    { l:'a) ¿Cuántos postres diferentes son posibles?', a:'5*3*2', v:'30', traps:[['5+3+2','Eliges sabor y topping y extra: se multiplica.']] },
    { l:'b) ¿Y si eres alérgico a las fresas y al chocolate?', a:'4*2*2', v:'16', traps:[['30-2','No basta restar 2: quitar la fresa elimina todos los postres que la usan.']] } ],
  sol:`<p>a) 5 · 3 · 2 = 30. b) Quedan 4 sabores y 2 toppings: 4 · 2 · 2 = 16.</p>`,
  bf:() => { const S = ['v','f','l','c','m'], T = ['ch','ca','cc'], E = ['cr','co']; const L = []; S.forEach(s => T.forEach(t => E.forEach(e => L.push([s,t,e])))); return [L.length, countIf(L, x => x[0] !== 'f' && x[1] !== 'ch')]; } },
{ id:'D8', src:'diap', t:'Configuración de un videojuego',
  q:`<p>Un videojuego se inicia eligiendo en 3 menús: número de jugadores (4 opciones), nivel (8 opciones) y velocidad (6 opciones). ¿En cuántas configuraciones se puede jugar?</p>`,
  a:'4*8*6', v:'192', sol:`<p>Tres pasos: 4 · 8 · 6 = 192.</p>` },
{ id:'D9', src:'diap', t:'Contraseñas de letras y dígitos',
  q:`<p>La contraseña de un sistema consta de 3 letras seguidas de 2 dígitos (alfabeto de 26 letras; se pueden repetir).</p>`,
  parts:[
    { l:'a) ¿Cuántas contraseñas son posibles?', a:'26^3*10^2', v:'1757600' },
    { l:'b) ¿Y si se distinguen mayúsculas y minúsculas?', a:'52^3*10^2', v:'14060800', traps:[['2*26^3*10^2','Cada letra por separado puede ser mayúscula o minúscula: son 52 opciones por letra, no un ×2 al final.']] } ],
  sol:`<p>a) 26 · 26 · 26 · 10 · 10 = 1,757,600. b) Cada letra tiene 52 opciones: 52³ · 10² = 14,060,800.</p>` },
{ id:'D10', src:'diap', t:'Hojas de respuestas',
  q:`<p>Un examen de opción múltiple tiene 20 preguntas con 4 respuestas posibles cada una y 10 preguntas más con 5 respuestas posibles cada una. ¿Cuántas hojas de respuestas diferentes son posibles?</p>`,
  a:'4^20*5^10', v:'10737418240000000000', traps:[['20*4+10*5','Cada pregunta multiplica las opciones; no se suman.'],['4^20+5^10','Contestas las 20 y las 10: se multiplica.']],
  sol:`<p>30 pasos: 20 con 4 opciones y 10 con 5. Total 4²⁰ · 5¹⁰ = 10,737,418,240,000,000,000 (unos 10¹⁹). Escríbelo como <code>4^20*5^10</code>.</p>` },
{ id:'D11', src:'diap', t:'NIP y contraseñas',
  q:`<p>Cuenta con la regla de la multiplicación.</p>`,
  parts:[
    { l:'a) ¿Cuántos NIP de 4 dígitos hay?', a:'10^4', v:'10000' },
    { l:'b) ¿Cuántos si no se repiten dígitos?', a:'10*9*8*7', v:'5040' },
    { l:'c) ¿Cuántas contraseñas de 8 caracteres hay si cada carácter es letra (mayúscula o minúscula) o dígito?', a:'62^8', v:'218340105584896', traps:[['36^8','Distinguiendo mayúsculas y minúsculas son 26 + 26 + 10 = 62 caracteres.']] } ],
  sol:`<p>a) 10⁴ = 10,000. b) 10 · 9 · 8 · 7 = 5,040. c) 62 caracteres posibles en cada una de 8 posiciones: 62⁸ ≈ 2.18 × 10¹⁴.</p>` },
{ id:'D12', src:'diap', t:'Sumar casos',
  q:`<p>Cuenta con la regla de la suma.</p>`,
  parts:[
    { l:'a) Mexicana tiene 3 vuelos diarios de México a Quintana Roo y Aeroméxico tiene 2. ¿De cuántas formas puedes volar?', a:'3+2', v:'5' },
    { l:'b) Escoges un alumno de entre dos grupos: uno de 25 y otro de 30. ¿De cuántas formas?', a:'25+30', v:'55' },
    { l:'c) Cruzas un lago en uno de 5 botes o en uno de 3 barcos. ¿De cuántas formas?', a:'5+3', v:'8', traps:[['15','Cruzas en bote <i>o</i> en barco, no en los dos: se suma.']] } ],
  sol:`<p>En los tres casos eliges una opción de un grupo <b>o</b> del otro, y no pueden pasar las dos: se suman.</p>` },
{ id:'D13', src:'diap', t:'Código Braille',
  q:`<p>Cada símbolo Braille es un rectángulo de seis puntos y cada punto puede estar levantado o plano. Si al menos uno de los seis puntos debe estar levantado, ¿cuántos símbolos se pueden representar?</p>`,
  a:'2^6-1', v:'63', traps:[['2^6','Falta quitar el símbolo con los seis puntos planos: al menos uno debe estar levantado.'],['6','Cada punto tiene dos estados y son 6 puntos: es 2⁶, no 6.'],['12','Los estados de los puntos se combinan: se multiplica 2 · 2 · … · 2.']],
  sol:`<p>Cada punto tiene 2 estados: 2⁶ = 64 rectángulos. El único prohibido es el de todos planos: 64 − 1 = 63.</p>` },
{ id:'D14', src:'extra', t:'Al menos un 7',
  q:`<p>¿Cuántos números de 3 cifras (del 100 al 999) tienen al menos un 7?</p>`,
  a:'900-8*9*9', v:'252', traps:[['3*100','Contar «el 7 en cada posición» repite los que tienen dos o tres sietes (como 777).'],['8*9*9','Esos son los que <b>no</b> tienen ningún 7. Réstalos del total.']],
  pista:'Complemento: total de números de 3 cifras menos los que no tienen ningún 7.',
  sol:`<p>Total: 900. Sin ningún 7: la primera cifra tiene 8 opciones (1–9 sin el 7) y las otras dos 9 (0–9 sin el 7): 8·9·9 = 648. Con al menos un 7: 900 − 648 = 252.</p>`,
  bf:() => countIf(range(100,999), n => String(n).includes('7')) },
{ id:'D15', src:'extra', t:'Cadenas de bits',
  q:`<p>Cadenas de 8 bits (ceros y unos).</p>`,
  parts:[
    { l:'a) ¿Cuántas tienen al menos un 1?', a:'2^8-1', v:'255' },
    { l:'b) ¿Cuántas tienen al menos un 0 y al menos un 1?', a:'2^8-2', v:'254' } ],
  sol:`<p>a) Total 2⁸ = 256 menos la única sin unos (00000000): 255. b) Quita las dos «aburridas», todo ceros y todo unos: 254.</p>`,
  bf:() => { const L = powA([0,1],8); return [countIf(L, p => p.includes(1)), countIf(L, p => p.includes(1) && p.includes(0))]; } },
{ id:'D16', src:'diap', t:'Ordenar todo',
  q:`<p>Cuenta los ordenamientos.</p>`,
  parts:[
    { l:'a) Las letras de PERMUTA', a:'7!', v:'5040' },
    { l:'b) El orden de ejecución de 6 microservicios en un pipeline', a:'6!', v:'720' },
    { l:'c) 10 sabores de helado en la vitrina de una heladería', a:'10!', v:'3628800' } ],
  sol:`<p>En los tres se ordenan todos los elementos y son distintos: 7! = 5,040, 6! = 720 y 10! = 3,628,800.</p>` },
{ id:'D17', src:'extra', t:'Cuentas con factoriales',
  q:`<p>Simplifica sin calcular los factoriales completos.</p>`,
  parts:[
    { l:'a) 10!/8! =', a:'10!/8!', v:'90' },
    { l:'b) 0! =', a:'1', v:'1' },
    { l:'c) n!/(n − 1)! en términos de n', k:'expr', dom:'nat', a:'n', ph:'Expresión en n' },
    { l:'d) (n + 2)!/n! en términos de n', k:'expr', dom:'nat', a:'(n+2)(n+1)', ph:'Expresión en n' } ],
  sol:`<p>a) 10!/8! = 10 · 9 = 90. b) 0! = 1 por convención. c) n! = n · (n − 1)!, así que n!/(n − 1)! = n. d) (n + 2)! = (n + 2)(n + 1) · n!, así que queda (n + 2)(n + 1).</p>` },
{ id:'D18', src:'diap', t:'Cadenas con ESTADIO',
  q:`<p>Para probar un analizador léxico se generan todas las cadenas posibles reorganizando las letras de la palabra ESTADIO. ¿Cuántas cadenas distintas se generan?</p>`,
  a:'7!', v:'5040', sol:`<p>ESTADIO tiene 7 letras y ninguna se repite (E, S, T, A, D, I, O): 7! = 5,040.</p>` },
{ id:'D19', src:'diap', t:'Calcula permutaciones',
  q:`<p>Ejercicios de la clase.</p>`,
  parts:[
    { l:'a) El número de 2-permutaciones de un conjunto de 7 elementos', a:'P(7,2)', v:'42' },
    { l:'b) P(4, 3)', a:'P(4,3)', v:'24' },
    { l:'c) P(5, 2) con las vocales', a:'P(5,2)', v:'20' } ],
  sol:`<p>P(7,2) = 7·6 = 42. P(4,3) = 4·3·2 = 24. P(5,2) = 5!/3! = 20.</p>` },
{ id:'D20', src:'diap', t:'Placas de automóvil',
  q:`<p>En cierto lugar todas las placas tienen cuatro letras seguidas de tres dígitos (26 letras; se pueden repetir letras y dígitos). ¿Cuántas placas diferentes son posibles?</p>`,
  a:'26^4*10^3', v:'456976000', traps:[['P(26,4)*P(10,3)','Las placas permiten repetir letras y dígitos (AAAA-000 es válida).']],
  sol:`<p>26⁴ · 10³ = 456,976,000. Ojo: aunque aparece junto a las permutaciones en la clase, se resuelve con la regla del producto porque se vale repetir.</p>` },
{ id:'D21', src:'diap', t:'Roles de un equipo de software',
  q:`<p>De un grupo de 10 ingenieros de software se elige un Product Owner, un Scrum Master y un Tech Lead. Nadie puede ocupar más de un rol. ¿Cuántas directivas diferentes se pueden formar?</p>`,
  a:'P(10,3)', v:'720', traps:[['C(10,3)','Los roles son distintos: importa quién es el Product Owner.'],['10^3','Nadie puede tener dos roles.']],
  sol:`<p>10 · 9 · 8 = 720.</p>` },
{ id:'D22', src:'diap', t:'Tokens bancarios',
  q:`<p>Un sistema bancario genera tokens de 4 caracteres usando únicamente {A, E, I, 1, 2, 3}, sin repetir caracteres en un mismo token. ¿Cuántos tokens únicos existen?</p>`,
  a:'P(6,4)', v:'360', traps:[['6^4','No se permiten caracteres repetidos.'],['C(6,4)','En un token el orden importa: A12E no es E21A.']],
  sol:`<p>6 · 5 · 4 · 3 = 360.</p>` },
{ id:'D23', src:'diap', t:'Anillo de servidores',
  q:`<p>Se conectan 8 servidores en una topología de anillo cerrado. Dos configuraciones son la misma si una es rotación de la otra. ¿Cuántas topologías distintas hay?</p>`,
  a:'PC(8)', v:'5040', traps:[['8!','Rotar el anillo da la misma topología: fija un servidor y ordena los otros 7.'],['7!/2','La clase considera iguales solo las rotaciones, no los reflejos. Con reflejos también iguales serían 2,520.']],
  sol:`<p>Permutación circular: fija un servidor y ordena los otros 7 a partir de él: (8 − 1)! = 7! = 5,040.</p>` },
{ id:'D24', src:'diap', t:'Libros por tema',
  q:`<p>En una estantería hay 8 libros distintos: 3 de matemáticas, 2 de historia y 3 de ciencia. ¿De cuántas formas pueden organizarse si los del mismo tema deben estar juntos?</p>`,
  a:'3!*3!*2!*3!', v:'432', traps:[['3!*2!*3!','Te falta ordenar los tres bloques entre sí: 3! formas.'],['3!','Eso solo ordena los bloques; falta ordenar los libros dentro de cada bloque.']],
  sol:`<p>Tres bloques que se ordenan de 3! formas; adentro, 3! (mate), 2! (historia) y 3! (ciencia): 6·6·2·6 = 432.</p>`,
  bf:() => countIf(permsA(['m1','m2','m3','h1','h2','c1','c2','c3']), p => ['m','h','c'].every(g => { const ix = p.map((x, i) => x[0] === g ? i : -1).filter(i => i >= 0); return ix[ix.length - 1] - ix[0] === ix.length - 1; })) },
{ id:'D25', src:'extra', t:'Juntos y separados',
  q:`<p>Cinco amigos, entre ellos Ana y Beto, se forman en una fila.</p>`,
  parts:[
    { l:'a) ¿En cuántas filas quedan Ana y Beto juntos?', a:'2*4!', v:'48', traps:[['4!','Dentro del bloque, Ana y Beto pueden ir AB o BA: ×2.']] },
    { l:'b) ¿En cuántas quedan separados?', a:'5!-2*4!', v:'72', traps:[['48','Esos son los que quedan juntos. Usa el complemento: total menos juntos.']] } ],
  sol:`<p>a) Bloque [AB] + 3 amigos = 4 objetos: 4! = 24, por 2 órdenes dentro del bloque: 48. b) Total 5! = 120 menos 48 = 72.</p>`,
  bf:() => { const P = permsA(['A','B','c','d','e']); const j = countIf(P, p => adjacent(p, 'A', 'B')); return [j, P.length - j]; } },
{ id:'D26', src:'extra', t:'Anagramas',
  q:`<p>¿Cuántos ordenamientos distintos tienen las letras de cada palabra?</p>`,
  parts:[
    { l:'a) CASA', a:'4!/2!', v:'12', traps:[['4!','Las dos A son iguales: cada palabra se contó 2! veces.']] },
    { l:'b) ANA', a:'3!/2!', v:'3' },
    { l:'c) PAPAYA', a:'PR(6,3,2)', v:'60', traps:[['6!/3!','La P también se repite (dos veces): divide también entre 2!.']] } ],
  sol:`<p>CASA: 4!/2! = 12. ANA: 3!/2! = 3 (ANA, AAN, NAA). PAPAYA: A ×3 y P ×2, así que 6!/(3!·2!) = 60.</p>`,
  bf:() => [uniquePermsA('CASA'.split('')).length, uniquePermsA('ANA'.split('')).length, uniquePermsA('PAPAYA'.split('')).length] },
{ id:'D27', src:'extra', t:'Posiciones con dos tipos',
  q:`<p>Cuando solo hay dos tipos, ordenar con repetidos es escoger posiciones.</p>`,
  parts:[
    { l:'a) ¿Cuántas cadenas de 8 bits tienen exactamente 3 unos?', a:'C(8,3)', v:'56' },
    { l:'b) ¿De cuántas formas se ordenan en fila 2 focos rojos y 3 azules (los del mismo color son iguales)?', a:'PR(5,2,3)', v:'10' } ],
  sol:`<p>a) 8!/(3!·5!) = C(8,3) = 56: escoges las 3 posiciones de los unos. b) 5!/(2!·3!) = 10 = C(5,2).</p>`,
  bf:() => [countIf(powA([0,1],8), p => countIf(p, x => x === 1) === 3), uniquePermsA(['R','R','A','A','A']).length] },
{ id:'D28', src:'diap', t:'Equipo de dos contra cargos',
  q:`<p>De un grupo de 4 personas (A, B, C, D):</p>`,
  parts:[
    { l:'a) ¿Cuántos equipos de 2 se pueden formar para un proyecto?', a:'C(4,2)', v:'6' },
    { l:'b) ¿De cuántas formas se eligen presidente y secretario?', a:'P(4,2)', v:'12' } ],
  sol:`<p>a) AB = BA: C(4,2) = 6. b) AB ≠ BA: P(4,2) = 12. Cada equipo de a) corresponde a 2! = 2 directivas de b).</p>`,
  bf:() => [combsA(['A','B','C','D'],2).length, permsA(['A','B','C','D'],2).length] },
{ id:'D29', src:'diap', t:'¿Combinación o permutación?',
  q:`<p>Ejercicios de la clase. Primero decide qué es y luego calcula.</p>`,
  parts:[
    { l:'a) A una reunión asisten 10 personas y se saludan todas. ¿Es combinación o permutación?', o:OPT_CP, a:0, w:'Un saludo entre Ana y Beto es el mismo que entre Beto y Ana.' },
    { l:'b) ¿Cuántos saludos hay?', a:'C(10,2)', v:'45' },
    { l:'c) Un estudiante elige 3 libros de una biblioteca que tiene 10. ¿Es combinación o permutación?', o:OPT_CP, a:0, w:'Se lleva los mismos libros sin importar el orden.' },
    { l:'d) ¿De cuántas formas puede hacerlo?', a:'C(10,3)', v:'120' } ],
  sol:`<p>Los dos son combinaciones: C(10,2) = 45 y C(10,3) = 120.</p>` },
{ id:'D30', src:'diap', t:'La bandera del artista',
  q:`<p>Un artista tiene 7 colores de pintura y quiere pintar una bandera de 3 franjas, cada una de un color distinto.</p>`,
  parts:[
    { l:'a) ¿De cuántas formas puede elegir los 3 colores?', a:'C(7,3)', v:'35' },
    { l:'b) ¿Cuántas banderas diferentes puede pintar? (Cambiar el orden de las franjas cambia la bandera.)', a:'P(7,3)', v:'210', traps:[['C(7,3)','Rojo-blanco-verde y verde-blanco-rojo son banderas distintas.']] } ],
  sol:`<p>a) Solo eliges qué colores: C(7,3) = 35. b) Además los ordenas en las franjas: P(7,3) = 210 = 35 · 3!.</p>` },
{ id:'D31', src:'diap', t:'Lotes de control de calidad',
  q:`<p>Control de calidad quiere probar 25 microprocesadores de los 300 que se fabrican cada día. ¿Cuántos lotes de prueba distintos hay?</p>`,
  a:'C(300,25)', v:'1953265141442868389822364184842211512', traps:[['P(300,25)','Un lote es un grupo de chips; no importa en qué orden se tomaron.']],
  sol:`<p>C(300,25), un número de 37 cifras (≈ 1.95 × 10³⁶). Escríbelo como <code>C(300,25)</code>; nadie espera que lo calcules a mano.</p>` },
{ id:'D32', src:'diap', t:'Comité con al menos una mujer',
  q:`<p>Un grupo de 10 estudiantes tiene 4 mujeres y 6 hombres.</p>`,
  parts:[
    { l:'a) ¿De cuántas formas se elige un representante del grupo?', a:'10', v:'10' },
    { l:'b) ¿De cuántas formas se elige un comité de 3 miembros?', a:'C(10,3)', v:'120' },
    { l:'c) ¿Y un comité de 3 donde al menos uno sea mujer?', a:'C(10,3)-C(6,3)', v:'100', traps:[['C(4,1)*C(9,2)','«Una mujer segura y luego 2 de los 9 restantes» cuenta varias veces el mismo comité: {Ana, Bety, Carlos} sale con Ana como la segura y con Bety como la segura.'],['C(4,1)*C(6,2)','Esos son solo los comités con exactamente una mujer. «Al menos una» también incluye 2 y 3 mujeres.']] } ],
  pista:'Para c) separa en 3 casos (1, 2 o 3 mujeres) o usa el complemento: total menos los comités sin mujeres.',
  sol:`<p>a) 4 + 6 = 10 (regla de la suma). b) C(10,3) = 120. c) Por casos: C(4,1)·C(6,2) + C(4,2)·C(6,1) + C(4,3)·C(6,0) = 60 + 36 + 4 = 100. Por complemento: 120 − C(6,3) = 120 − 20 = 100.</p>`,
  bf:() => { const G = ['M1','M2','M3','M4','H1','H2','H3','H4','H5','H6']; const C3 = combsA(G,3); return [G.length, C3.length, countIf(C3, c => c.some(x => x[0] === 'M'))]; } },
{ id:'D33', src:'diap', t:'Siete de diez preguntas',
  q:`<p>Un estudiante debe responder siete de las diez preguntas de un examen. ¿De cuántas formas puede elegir si…</p>`,
  parts:[
    { l:'a) no hay restricciones?', a:'C(10,7)', v:'120' },
    { l:'b) debe contestar las dos primeras preguntas?', a:'C(8,5)', v:'56', traps:[['C(8,7)','Las dos primeras ya cuentan entre las 7: solo eliges 5 más de las 8 restantes.']] },
    { l:'c) debe responder al menos cuatro de las seis primeras?', a:'C(6,4)*C(4,3)+C(6,5)*C(4,2)+C(6,6)*C(4,1)', v:'100', traps:[['C(6,4)*C(6,3)','Separa por casos: exactamente 4, 5 o 6 de las primeras seis, y el resto de las últimas cuatro.']] } ],
  sol:`<p>a) C(10,7) = 120. b) Las dos primeras van seguro; eliges 5 de las 8 restantes: C(8,5) = 56.</p><p>c) Casos: 4 de las primeras 6 y 3 de las últimas 4: 15·4 = 60; 5 y 2: 6·6 = 36; 6 y 1: 1·4 = 4. Total 100.</p>`,
  bf:() => { const C = combsA(range(1,10),7); return [C.length, countIf(C, c => c.includes(1) && c.includes(2)), countIf(C, c => countIf(c, x => x <= 6) >= 4)]; } },
{ id:'D34', src:'diap', t:'Triángulos con puntos colineales',
  q:`<p>¿Cuántos triángulos se pueden formar con 8 puntos en un plano, si 3 de ellos son colineales (y no hay otros tres alineados)?</p>`,
  a:'C(8,3)-1', v:'55', traps:[['C(8,3)','Los 3 puntos colineales no forman triángulo: réstalo.'],['C(5,3)','Puedes usar 1 o 2 de los puntos colineales; solo los tres juntos fallan.']],
  sol:`<p>Todos los tríos menos el trío colineal: C(8,3) − 1 = 56 − 1 = 55.</p>`,
  bf:() => countIf(combsA(range(1,8),3), c => !(c[0] === 1 && c[1] === 2 && c[2] === 3)) },
{ id:'D35', src:'extra', t:'Ingenieros y diseñadoras',
  q:`<p>Se elige un comité de 4 personas entre 5 ingenieros y 4 diseñadoras (una de ellas es Ana).</p>`,
  parts:[
    { l:'a) Con exactamente 2 diseñadoras', a:'C(5,2)*C(4,2)', v:'60' },
    { l:'b) Con al menos un ingeniero', a:'C(9,4)-C(4,4)', v:'125' },
    { l:'c) Si Ana debe estar en el comité', a:'C(8,3)', v:'56' } ],
  sol:`<p>a) 2 de 5 ingenieros y 2 de 4 diseñadoras: 10·6 = 60. b) Total C(9,4) = 126 menos el único comité solo de diseñadoras: 125. c) Ana adentro; eliges 3 de los 8 restantes: 56.</p>`,
  bf:() => { const G = ['I1','I2','I3','I4','I5','D1','D2','D3','D4']; const C = combsA(G,4); return [countIf(C, c => countIf(c, x => x[0] === 'D') === 2), countIf(C, c => c.some(x => x[0] === 'I')), countIf(C, c => c.includes('D1'))]; } },
{ id:'D36', src:'diap', t:'Cuatro equipos de cuatro',
  q:`<p>¿De cuántas maneras se pueden formar 4 equipos de 4 integrantes con un grupo de 16 personas?</p>`,
  a:'C(16,4)*C(12,4)*C(8,4)*C(4,4)', v:'63063000', alt:[['C(16,4)*C(12,4)*C(8,4)/4!','También es correcto si los equipos no tienen nombre ni orden: entonces se divide entre 4! = 24 y quedan 2,627,625. La diapositiva cuenta los equipos como distintos (equipo 1, 2, 3 y 4).']],
  traps:[['C(16,4)','Ese es solo el primer equipo. Los demás se eligen de los que quedan.']],
  sol:`<p>Primer equipo C(16,4), segundo C(12,4), tercero C(8,4) y el último C(4,4) = 1: 1820 · 495 · 70 · 1 = 63,063,000 (respuesta de la diapositiva). Si los equipos fueran intercambiables, dividirías entre 4!.</p>` },
{ id:'D37', src:'diap', t:'Partidas de bridge',
  q:`<p>Una partida de bridge reparte las 52 cartas en cuatro manos de 13 cartas, una para cada jugador. ¿Cuántas partidas distintas se pueden jugar?</p>`,
  a:'C(52,13)*C(39,13)*C(26,13)', v:'53644737765488792839237440000', traps:[['C(52,13)','Esa es solo la mano del primer jugador.'],['C(52,13)^4','Cada jugador elige de las cartas que quedan, no de las 52.']],
  pista:'Calcula cuántas manos le puedes dar a cada jugador con las cartas que quedan.',
  sol:`<p>Al primero C(52,13), al segundo C(39,13), al tercero C(26,13) y al último lo que queda (1 forma). Producto ≈ 5.36 × 10²⁸. Equivale a 52!/(13!)⁴.</p>` },
{ id:'D38', src:'diap', t:'Ratones de laboratorio',
  q:`<p>Se probarán dos medicamentos con 60 ratones numerados: el medicamento A se da a 22 ratones, el B a otros 22 y los 16 restantes son de control. ¿De cuántas formas se pueden asignar los tratamientos?</p>`,
  a:'C(60,22)*C(38,22)', v:'314790828599338321972833000', traps:[['C(60,22)*C(60,22)','Los ratones del grupo B se eligen de los 38 que quedan, no de los 60.'],['C(60,22)','Falta elegir a los del medicamento B.']],
  sol:`<p>Elige los 22 del medicamento A: C(60,22). De los 38 que quedan elige los 22 del B: C(38,22). Los 16 restantes son de control (1 forma). Es 60!/(22!·22!·16!).</p>` },
{ id:'D39', src:'extra', t:'Tareas a servidores',
  q:`<p>Hay 8 tareas distintas y 3 servidores: el A recibe 3 tareas, el B recibe 3 y el C recibe 2. ¿De cuántas formas se pueden asignar?</p>`,
  a:'C(8,3)*C(5,3)*C(2,2)', v:'560', sol:`<p>C(8,3) · C(5,3) · C(2,2) = 56 · 10 · 1 = 560 = 8!/(3!·3!·2!).</p>` },
{ id:'D40', src:'extra', t:'Parejas sin nombre',
  q:`<p>¿De cuántas formas se pueden dividir 6 personas en 3 parejas, si las parejas no tienen nombre ni orden?</p>`,
  a:'C(6,2)*C(4,2)*C(2,2)/3!', v:'15', traps:[['C(6,2)*C(4,2)','Así cuentas «pareja 1, pareja 2, pareja 3». Como no tienen nombre, cada reparto aparece 3! = 6 veces: divide entre 6.']],
  sol:`<p>Con nombre serían 15 · 6 · 1 = 90. Cada división en parejas aparece 3! = 6 veces (una por cada forma de numerar las parejas): 90/6 = 15. Otra forma: la persona 1 escoge pareja (5), la siguiente libre escoge (3), y la última pareja queda: 5·3 = 15.</p>`,
  bf:() => { const count = arr => arr.length === 0 ? 1 : arr.slice(1).reduce((s, x, i) => s + count(arr.slice(1).filter((_, j) => j !== i)), 0); return count(range(1,6)); } },
{ id:'D41', src:'extra', t:'¿Qué herramienta?',
  q:`<p>Para cada problema elige la herramienta principal.</p>`,
  parts:[
    { l:'a) Tres premios distintos para 20 alumnos; uno puede ganar varios.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:0, w:'Orden importa y se repite: 20³.' },
    { l:'b) Escoger 3 asignaturas de 6 optativas.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:2, w:'Sin orden y sin repetir.' },
    { l:'c) Presidente y secretario entre 10 vecinos.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:1, w:'Cargos distintos, sin repetir persona.' },
    { l:'d) Ordenar las letras de BANANA.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:3, w:'Se ordenan todas y hay letras repetidas.' },
    { l:'e) Diálogos sin intérprete: 40 solo hablan inglés y 20 solo alemán.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:4, w:'O es pareja de inglés o pareja de alemán: C(40,2) + C(20,2).' },
    { l:'f) Manos de 5 cartas de una baraja de 40.', o:['Producto (nʳ)','P(n, r)','C(n, r)','n!/(a!·b!·…)','Suma de casos'], a:2, w:'Una mano no tiene orden.' } ],
  sol:`<p>Las tres preguntas: ¿pasos o casos? ¿importa el orden? ¿se puede repetir? Con eso se decide cada uno.</p>` },
{ id:'D42', src:'extra', t:'Parecidos pero distintos',
  q:`<p>Hay 8 personas. Fíjate en qué cambia entre un inciso y otro.</p>`,
  parts:[
    { l:'a) Formar un comité de 3', a:'C(8,3)', v:'56' },
    { l:'b) Elegir presidente, secretario y tesorero', a:'P(8,3)', v:'336' },
    { l:'c) Dar 3 premios distintos; alguien puede ganar varios', a:'8^3', v:'512' },
    { l:'d) Dar 3 premios iguales; nadie gana dos', a:'C(8,3)', v:'56', traps:[['P(8,3)','Si los premios son iguales, solo importa quiénes los ganan.']] } ],
  sol:`<p>a) Sin orden: 56. b) Cargos distintos: 336. c) Orden y repetición: 512. d) Premios iguales sin repetir: es lo mismo que el comité, 56.</p>` },
{ id:'D43', src:'extra', t:'La palabra LIBRO',
  q:`<p>Con las letras de LIBRO (todas distintas):</p>`,
  parts:[
    { l:'a) ¿Cuántas «palabras» de 3 letras distintas?', a:'P(5,3)', v:'60' },
    { l:'b) ¿Cuántos grupos de 3 letras (sin orden)?', a:'C(5,3)', v:'10' },
    { l:'c) ¿Cuántas palabras de 3 letras si se pueden repetir?', a:'5^3', v:'125' },
    { l:'d) ¿Cuántos ordenamientos de las 5 letras?', a:'5!', v:'120' } ],
  sol:`<p>a) 5·4·3 = 60. b) 60/3! = 10. c) 5³ = 125. d) 5! = 120.</p>`,
  bf:() => [permsA('LIBRO'.split(''),3).length, combsA('LIBRO'.split(''),3).length, powA('LIBRO'.split(''),3).length, permsA('LIBRO'.split('')).length] },
{ id:'D44', src:'diap', t:'Números telefónicos',
  q:`<p>Un número telefónico tiene siete cifras. La primera debe estar entre 2 y 9; la segunda y la tercera entre 1 y 9; las restantes entre 0 y 9 (todas inclusive). ¿Cuántos números distintos se pueden formar?</p>`,
  a:'8*9*9*10^4', v:'6480000', traps:[['7*8*8*10^4','Cuenta los extremos: del 2 al 9 hay 8 dígitos y del 1 al 9 hay 9.']],
  sol:`<p>Primera cifra 8 opciones, segunda y tercera 9 cada una, y las otras cuatro 10 cada una: 8·9·9·10⁴ = 6,480,000.</p>` },
{ id:'D45', src:'diap', t:'Direcciones IP',
  q:`<p>Una dirección IP tiene 32 bits. ¿Cuántas direcciones cumplen esto?: el primer bit es 0, los siguientes 7 bits no pueden ser todos 1 y los otros 24 bits no pueden ser ni todos unos ni todos ceros.</p>`,
  a:'(2^7-1)*(2^24-2)', v:'2130706178', traps:[['2^7*2^24','Faltan las restricciones: quita el caso «los 7 bits en 1» y los casos «24 bits todos en 0 o todos en 1».'],['2^31-3','Cada bloque tiene sus propias restricciones y los bloques se multiplican; no se restan del total de 31 bits.']],
  sol:`<p>El primer bit ya está fijo. Bloque de 7 bits: 2⁷ − 1 = 127. Bloque de 24 bits: 2²⁴ − 2 = 16,777,214. Producto: 2,130,706,178.</p>` },
{ id:'D46', src:'diap', t:'Cadenas de bits',
  q:`<p>Cuenta cadenas de bits.</p>`,
  parts:[
    { l:'a) ¿Cuántas cadenas de 10 bits hay?', a:'2^10', v:'1024' },
    { l:'b) ¿Cuántas tienen exactamente 3 unos?', a:'C(10,3)', v:'120', traps:[['P(10,3)','Los unos son iguales entre sí: solo importa en qué posiciones van.']] },
    { l:'c) ¿Cuántas tienen al menos un 1?', a:'2^10-1', v:'1023' },
    { l:'d) ¿Cuántos números de 16 bits tienen exactamente 4 unos? (pregunta de la intro de tu clase)', a:'C(16,4)', v:'1820' } ],
  sol:`<p>a) 2¹⁰ = 1,024. b) Escoge las 3 posiciones de los unos: C(10,3) = 120. c) Todas menos 0000000000: 1,023. d) C(16,4) = 1,820.</p>`,
  bf:() => { const L = powA([0,1],10); return [L.length, countIf(L, p => countIf(p, x => x === 1) === 3), countIf(L, p => p.includes(1)), null]; } },
{ id:'D47', src:'diap', t:'Contar funciones',
  q:`<p>Sean A = {1, 2, 3} y B = {a, b, c, d, e}.</p>`,
  parts:[
    { l:'a) ¿Cuántas funciones f : A → B hay?', a:'5^3', v:'125', traps:[['3^5','Cada elemento de A (3) escoge imagen en B (5): 5·5·5. Al revés serían funciones de B en A.']] },
    { l:'b) ¿Cuántas de ellas son inyectivas?', a:'P(5,3)', v:'60' },
    { l:'c) ¿Cuántas funciones biyectivas hay de {1, 2, 3, 4} en sí mismo?', a:'4!', v:'24' },
    { l:'d) ¿Cuántas funciones hay de A en {0, 1}?', a:'2^3', v:'8' } ],
  sol:`<p>a) Cada uno de los 3 elementos elige imagen entre 5: 5³ = 125 (la diapositiva: con |A| = m y |B| = n hay nᵐ). b) Sin repetir imagen: 5·4·3 = 60. c) Una biyección de un conjunto en sí mismo es una permutación: 4! = 24. d) 2³ = 8, igual que el número de subconjuntos de A.</p>`,
  bf:() => { const F = powA(['a','b','c','d','e'],3); return [F.length, countIf(F, f => new Set(f).size === 3), permsA(range(1,4)).length, powA([0,1],3).length]; } },
{ id:'D48', src:'extra', t:'Nombres de usuario',
  q:`<p>Un usuario tiene 2 letras (26 posibles, se pueden repetir) seguidas de 4 dígitos sin repetir. ¿Cuántos usuarios distintos hay?</p>`,
  a:'26^2*P(10,4)', v:'3407040', traps:[['26^2*10^4','Los dígitos no se repiten: 10·9·8·7.'],['P(26,2)*P(10,4)','Las letras sí se pueden repetir.']],
  sol:`<p>26² · (10·9·8·7) = 676 · 5,040 = 3,407,040.</p>` },
{ id:'D50', src:'diap', t:'Una docena de donas',
  q:`<p>¿De cuántas maneras diferentes podemos elegir una docena de donas si hay 5 tipos? (Pregunta de la intro de tu clase.)</p>`,
  a:'C(16,4)', v:'1820', traps:[['5^12','Eso cuenta docenas ordenadas (primera dona, segunda…). En la caja no importa el orden.'],['C(12,5)','Usa estrellas y barras: 12 donas + 4 barras = 16 posiciones.']],
  sol:`<p>Estrellas y barras: 12 estrellas y 4 barras en 16 posiciones. CR(5,12) = C(16,4) = 1,820.</p>`,
  bf:() => { let n = 0; for (let a = 0; a <= 12; a++) for (let b = 0; a + b <= 12; b++) for (let c = 0; a + b + c <= 12; c++) for (let d = 0; a + b + c + d <= 12; d++) n++; return n; } },
{ id:'D51', src:'libro', t:'Fichas de dominó',
  q:`<p>Se quiere construir un dominó con los números del 0 al 6. ¿Cuántas fichas tendrá?</p>`,
  a:'CR(7,2)', v:'28', traps:[['C(7,2)','Faltan las mulas (0|0, 1|1, …, 6|6): una ficha puede repetir número.'],['7^2','La ficha 2|5 es la misma que 5|2.']],
  sol:`<p>Parejas sin orden que pueden repetir: CR(7,2) = C(8,2) = 28. O bien: C(7,2) = 21 fichas con números distintos más 7 mulas.</p>`,
  bf:() => multisetCombsA(range(0,6),2).length },
{ id:'D52', src:'extra', t:'Vaso de helado',
  q:`<p>Un vaso lleva 3 bolas de helado y hay 4 sabores. En el vaso no importa el orden y se puede repetir sabor. ¿Cuántos vasos distintos hay?</p>`,
  a:'CR(4,3)', v:'20', traps:[['C(4,3)','Se puede repetir sabor (tres de chocolate es válido).'],['4^3','En el vaso no importa el orden de las bolas.']],
  sol:`<p>CR(4,3) = C(6,3) = 20.</p>`,
  bf:() => multisetCombsA(['v','c','f','m'],3).length }
);

/* ======================= BANCO DEL EXAMEN ======================= */
EX.push(
{ id:'X1', src:'examen', b:'fun', t:'Una función finita',
  q:`<p>f : {1, 2, 3, 4} → {a, b, c} con f(1) = a, f(2) = c, f(3) = a, f(4) = b.</p>`,
  parts:[
    { l:'a) Rango de f', k:'set', a:'{a,b,c}' }, { l:'b) Imagen inversa de a', k:'set', a:'{1,3}' },
    { l:'c) ¿Es inyectiva?', o:SINO, a:1, w:'f(1) = f(3).' }, { l:'d) ¿Es sobreyectiva?', o:SINO, a:0, w:'a, b y c reciben flecha.' } ],
  sol:`<p>Rango {a, b, c} = codominio, así que es sobreyectiva. f(1) = f(3) = a, así que no es inyectiva; la imagen inversa de a es {1, 3}.</p>` },
{ id:'X2', src:'examen', b:'fun', t:'Composición e inversa',
  q:`<p>f(x) = 3x + 2 y g(x) = x², de ℝ en ℝ.</p>`,
  parts:[
    { l:'a) (g ∘ f)(x) =', k:'expr', vars:['x'], a:'(3x+2)^2', ph:'Expresión en x', traps:[['3x^2+2','Esa es f ∘ g.']] },
    { l:'b) (f ∘ g)(1) =', a:'5', v:'5' }, { l:'c) (g ∘ f)(1) =', a:'25', v:'25' },
    { l:'d) f⁻¹(y) =', k:'expr', vars:['y'], a:'(y-2)/3', ph:'Expresión en y' } ],
  sol:`<p>(g ∘ f)(x) = (3x + 2)². (f ∘ g)(1) = 3·1 + 2 = 5. (g ∘ f)(1) = 5² = 25. Despejando y = 3x + 2: f⁻¹(y) = (y − 2)/3.</p>` },
{ id:'X3', src:'examen', b:'fun', t:'Clasifica en los enteros',
  q:`<p>Todas van de ℤ en ℤ.</p>`,
  parts:[
    { l:'a) f(n) = n + 5', o:OPT_CLAS, a:2, w:'Su inversa es n − 5.' },
    { l:'b) f(n) = |n|', o:OPT_CLAS, a:3, w:'f(−1) = f(1) y los negativos no se alcanzan.' },
    { l:'c) f(n) = 3n', o:OPT_CLAS, a:0, w:'Inyectiva, pero el 1 no es 3n para ningún entero.' } ],
  sol:`<p>Busca contraejemplos de inyectividad (dos n con la misma imagen) y valores del codominio sin preimagen.</p>` },
{ id:'X4', src:'examen', b:'prod', t:'Placas sin vocal al inicio',
  q:`<p>Una placa tiene 3 letras (26 posibles, se pueden repetir) y 4 dígitos (se pueden repetir). La primera letra no puede ser vocal. ¿Cuántas placas hay?</p>`,
  a:'21*26^2*10^4', v:'141960000', traps:[['26^3*10^4','Falta la restricción: la primera letra tiene 26 − 5 = 21 opciones.']],
  sol:`<p>21 · 26 · 26 · 10⁴ = 141,960,000.</p>` },
{ id:'X5', src:'examen', b:'prod', t:'Menú del día',
  q:`<p>Un menú ofrece 4 entradas, 5 platos fuertes y 3 postres. Siempre pides un plato fuerte y además una entrada o un postre (uno de los dos, no ambos). ¿Cuántas comidas distintas puedes armar?</p>`,
  a:'5*(4+3)', v:'35', traps:[['4*5*3','No pides entrada y postre a la vez: es entrada o postre (se suman), y eso por el plato fuerte.'],['4+5+3','El plato fuerte siempre va: se multiplica por las opciones del acompañamiento.']],
  sol:`<p>Plato fuerte (5) y acompañamiento (4 entradas o 3 postres = 7): 5 · 7 = 35.</p>` },
{ id:'X6', src:'examen', b:'prod', t:'Con algún dígito repetido',
  q:`<p>¿Cuántas cadenas de 6 dígitos (de 000000 a 999999) tienen al menos un dígito repetido?</p>`,
  a:'10^6-P(10,6)', v:'848800', traps:[['P(10,6)','Esas son las que no repiten. Usa el complemento: total menos las que no repiten.']],
  sol:`<p>Total 10⁶ = 1,000,000. Sin repetir: P(10,6) = 151,200. Con al menos uno repetido: 848,800.</p>` },
{ id:'X7', src:'examen', b:'perm', t:'Dos libros que no van juntos',
  q:`<p>7 libros distintos se acomodan en un estante. Dos de ellos no pueden quedar juntos. ¿De cuántas formas?</p>`,
  a:'7!-2*6!', v:'3600', traps:[['2*6!','Esas son las acomodaciones con los dos juntos. Réstalas del total.']],
  sol:`<p>Total 7! = 5,040. Juntos: bloque + 5 libros = 6 objetos, 6!·2 = 1,440. Separados: 5,040 − 1,440 = 3,600.</p>`,
  bf:() => countIf(permsA(range(1,7)), p => !adjacent(p, 1, 2)) },
{ id:'X8', src:'examen', b:'perm', t:'COCODRILO',
  q:`<p>¿Cuántos ordenamientos distintos tienen las letras de COCODRILO?</p>`,
  a:'PR(9,2,3)', v:'30240', traps:[['9!','Hay letras repetidas: C dos veces y O tres veces.']],
  sol:`<p>9 letras con C ×2 y O ×3: 9!/(2!·3!) = 30,240.</p>`,
  bf:() => uniquePermsA('COCODRILO'.split('')).length },
{ id:'X9', src:'examen', b:'perm', t:'Mesa redonda con pareja',
  q:`<p>6 personas se sientan en una mesa redonda y Ana y Beto deben quedar juntos. Las rotaciones cuentan como la misma acomodación. ¿De cuántas formas?</p>`,
  a:'2*4!', v:'48', traps:[['2*5!','En la mesa redonda el bloque y las otras 4 personas son 5 objetos en círculo: (5 − 1)!.']],
  sol:`<p>Bloque [Ana-Beto] + 4 personas = 5 objetos en círculo: (5 − 1)! = 24, por 2 órdenes dentro del bloque: 48.</p>`,
  bf:() => countIf(permsA(range(2,6)).map(p => [1].concat(p)), p => { const j = p.indexOf(2); return j === 1 || j === 5; }) },
{ id:'X10', src:'examen', b:'cond', t:'Ocho de doce preguntas',
  q:`<p>En un examen de 12 preguntas debes contestar 8 y al menos 3 de las primeras 5. ¿De cuántas formas puedes elegir?</p>`,
  a:'C(5,3)*C(7,5)+C(5,4)*C(7,4)+C(5,5)*C(7,3)', v:'420',
  sol:`<p>Casos: 3 de las primeras y 5 de las otras 7: 10·21 = 210; 4 y 4: 5·35 = 175; 5 y 3: 1·35 = 35. Total 420. (Complemento: C(12,8) = 495 menos 75 con menos de 3.)</p>`,
  bf:() => countIf(combsA(range(1,12),8), c => countIf(c, x => x <= 5) >= 3) },
{ id:'X11', src:'examen', b:'cond', t:'Al menos dos mujeres',
  q:`<p>Se elige un comité de 5 personas entre 7 hombres y 6 mujeres. ¿Cuántos comités tienen al menos 2 mujeres?</p>`,
  a:'C(13,5)-C(7,5)-C(6,1)*C(7,4)', v:'1056', traps:[['C(13,5)-C(7,5)','Eso es «al menos una». Quita también los que tienen exactamente una mujer.']],
  sol:`<p>Total C(13,5) = 1,287. Sin mujeres: C(7,5) = 21. Con una: 6·C(7,4) = 210. Al menos dos: 1,287 − 21 − 210 = 1,056.</p>`,
  bf:() => countIf(combsA(range(1,13),5), c => countIf(c, x => x <= 6) >= 2) },
{ id:'X12', src:'examen', b:'cond', t:'Ana y Beto no juntos',
  q:`<p>De 11 personas, entre ellas Ana y Beto, se forma un comité de 4. Ana y Beto no pueden estar los dos. ¿Cuántos comités hay?</p>`,
  a:'C(11,4)-C(9,2)', v:'294', traps:[['C(9,4)','Así quitas a los dos; pero puede estar uno de ellos.']],
  sol:`<p>Total C(11,4) = 330 menos los que tienen a ambos (eliges 2 más de 9: 36): 294.</p>`,
  bf:() => countIf(combsA(range(1,11),4), c => !(c.includes(1) && c.includes(2))) },
{ id:'X13', src:'examen', b:'comb', t:'Diagonales del octágono',
  q:`<p>¿Cuántas diagonales tiene un octágono?</p>`,
  a:'C(8,2)-8', v:'20', traps:[['C(8,2)','Esa cuenta incluye los 8 lados del octágono, que no son diagonales.']],
  sol:`<p>Segmentos entre 8 vértices: C(8,2) = 28, menos los 8 lados: 20.</p>`,
  bf:() => countIf(combsA(range(0,7),2), c => { const d = c[1] - c[0]; return d !== 1 && d !== 7; }) },
{ id:'X14', src:'examen', b:'comb', t:'Pizzas de tres ingredientes',
  q:`<p>Una pizzería ofrece 10 ingredientes y cada pizza lleva 3 distintos. ¿Cuántas pizzas distintas hay?</p>`,
  a:'C(10,3)', v:'120', traps:[['P(10,3)','La pizza de jamón, piña y queso es la misma en cualquier orden.']],
  sol:`<p>C(10,3) = 120.</p>` },
{ id:'X15', src:'examen', b:'comb', t:'Liga a dos vueltas',
  q:`<p>En una liga de 12 equipos todos juegan contra todos dos veces (ida y vuelta). ¿Cuántos partidos hay?</p>`,
  a:'2*C(12,2)', v:'132', traps:[['C(12,2)','A dos vueltas cada pareja juega dos veces.']],
  sol:`<p>2·C(12,2) = 132, que es lo mismo que P(12,2): cada partido tiene local y visitante.</p>` },
{ id:'X16', src:'examen', b:'mix', t:'Mayores que 5000',
  q:`<p>¿Cuántos números de 4 cifras distintas, usando los dígitos del 1 al 9, son mayores que 5000?</p>`,
  a:'5*P(8,3)', v:'1680', sol:`<p>Primera cifra del 5 al 9 (5 opciones) y las otras tres sin repetir de las 8 que quedan: 5·8·7·6 = 1,680.</p>`,
  bf:() => countIf(range(5001,9999), n => { const s = String(n); return !s.includes('0') && new Set(s).size === 4; }) },
{ id:'X17', src:'examen', b:'mix', t:'Pares de cifras distintas',
  q:`<p>¿Cuántos números de 3 cifras (sin empezar con 0) tienen sus cifras distintas y son pares?</p>`,
  a:'9*8+4*8*8', v:'328', traps:[['5*9*8','El 0 complica: si termina en 0, la primera cifra tiene 9 opciones; si termina en 2, 4, 6 u 8, la primera no puede ser 0 ni la última.']],
  pista:'Separa en dos casos: termina en 0 o termina en 2, 4, 6 u 8.',
  sol:`<p>Termina en 0: 9·8 = 72. Termina en 2, 4, 6 u 8 (4 opciones): la primera cifra no puede ser 0 ni la última (8 opciones) y la del medio 8: 4·8·8 = 256. Total 328.</p>`,
  bf:() => countIf(range(100,999), n => n % 2 === 0 && new Set(String(n)).size === 3) },
{ id:'X18', src:'examen', b:'mix', t:'Ana en el podio',
  q:`<p>En una carrera de 8 corredoras, ¿de cuántas formas pueden quedar los 3 primeros lugares si Ana debe estar en el podio?</p>`,
  a:'3*P(7,2)', v:'126', traps:[['P(7,2)','Ana puede quedar 1ª, 2ª o 3ª: ×3.']],
  sol:`<p>Lugar de Ana: 3 opciones. Los otros dos lugares con las 7 restantes: 7·6 = 42. Total 126. (Complemento: P(8,3) − P(7,3) = 336 − 210.)</p>`,
  bf:() => countIf(permsA(range(1,8),3), p => p.includes(1)) },
{ id:'X19', src:'examen', b:'mix', t:'Tareas a programadores',
  q:`<p>Hay 5 tareas distintas y 3 programadores. Cada tarea se asigna a un programador y alguien puede quedarse sin tareas. ¿De cuántas formas?</p>`,
  a:'3^5', v:'243', traps:[['5^3','Cada tarea (5) escoge programador (3): 3⁵.']],
  sol:`<p>Cada una de las 5 tareas elige entre 3 programadores: 3⁵ = 243. Es contar funciones de las tareas en los programadores.</p>` }
);
